fn parse_int(s: Str) -> Option<Int> {
    let mut digits: Vec<Int> = vec()
    for c in chars(s) {
        match c {
            Str(n) => digits.push(n - 48),
            _ => returnNone(),
        }
    }
    let mut result = 0
    for n in digits {
        result = result * 10 + n
    }
    Some(result)
}

